def solve(inputs: dict) -> float:
    # Chinese remainder theorem for pairwise-coprime moduli.
    def pick(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        return None

    residues = pick('residues', 'remainders', 'a', 'r', 'values')
    moduli = pick('moduli', 'mods', 'm')
    if residues is None or moduli is None:
        # Optionally accept a list of (residue, modulus) congruences.
        pairs = pick('congruences', 'pairs')
        if pairs is None:
            raise ValueError('Missing residues or moduli')
        residues = [p[0] for p in pairs]
        moduli = [p[1] for p in pairs]

    if len(residues) != len(moduli):
        raise ValueError('Mismatched residue and modulus counts')

    x, combined_modulus = 0, 1
    for residue, modulus in zip(residues, moduli):
        residue, modulus = int(residue), int(modulus)
        if modulus <= 0:
            raise ValueError('Moduli must be positive')
        # Solve x + combined_modulus*k == residue (mod modulus).
        k = ((residue - x) * pow(combined_modulus, -1, modulus)) % modulus
        x += combined_modulus * k
        combined_modulus *= modulus
        x %= combined_modulus
    return float(x)

